"""
Bounded FIFO task queue with priorities, cancellation, retries, and thread-safe wrapper.
"""

import threading
import heapq
import time
import unittest
from typing import Any, Callable, Optional, List, Tuple
from dataclasses import dataclass, field
from enum import Enum
from concurrent.futures import Future


class TaskState(Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    CANCELLED = "cancelled"
    FAILED = "failed"


@dataclass(order=True)
class Task:
    priority: int
    sequence: int = field(compare=True)
    func: Callable = field(compare=False)
    args: tuple = field(default=(), compare=False)
    kwargs: dict = field(default_factory=dict, compare=False)
    max_retries: int = field(default=0, compare=False)
    retry_delay: float = field(default=0.0, compare=False)
    state: TaskState = field(default=TaskState.PENDING, compare=False)
    future: Optional[Future] = field(default=None, compare=False)
    result: Any = field(default=None, compare=False)
    exception: Optional[Exception] = field(default=None, compare=False)
    retries_done: int = field(default=0, compare=False)
    cancelled_event: threading.Event = field(default_factory=threading.Event, compare=False)

    def __post_init__(self):
        if self.future is None:
            self.future = Future()

    def cancel(self) -> bool:
        if self.state in (TaskState.COMPLETED, TaskState.FAILED, TaskState.CANCELLED):
            return False
        self.cancelled_event.set()
        self.state = TaskState.CANCELLED
        if self.future and not self.future.done():
            self.future.cancel()
        return True

    def is_cancelled(self) -> bool:
        return self.cancelled_event.is_set()


class BoundedPriorityQueue:
    """Thread-safe bounded priority queue for tasks."""

    def __init__(self, maxsize: int = 100):
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")
        self._maxsize = maxsize
        self._heap: List[Task] = []
        self._lock = threading.Lock()
        self._not_empty = threading.Condition(self._lock)
        self._not_full = threading.Condition(self._lock)
        self._sequence = 0
        self._closed = False
        self._tasks: dict = {}  # task_id -> Task for lookup

    @property
    def maxsize(self) -> int:
        return self._maxsize

    def __len__(self) -> int:
        with self._lock:
            return len(self._heap)

    def put(self, task: Task, block: bool = True, timeout: Optional[float] = None) -> bool:
        """Put a task into the queue. Returns True if successful, False if queue is closed."""
        with self._lock:
            if self._closed:
                return False
            while len(self._heap) >= self._maxsize:
                if not block:
                    return False
                if timeout is not None:
                    if not self._not_full.wait(timeout):
                        return False
                else:
                    self._not_full.wait()
                if self._closed:
                    return False
            task.sequence = self._sequence
            self._sequence += 1
            heapq.heappush(self._heap, task)
            self._tasks[id(task)] = task
            self._not_empty.notify()
            return True

    def get(self, block: bool = True, timeout: Optional[float] = None) -> Optional[Task]:
        """Get a task from the queue. Returns None if queue is empty and non-blocking or timed out."""
        with self._lock:
            while len(self._heap) == 0:
                if self._closed:
                    return None
                if not block:
                    return None
                if timeout is not None:
                    if not self._not_empty.wait(timeout):
                        return None
                else:
                    self._not_empty.wait()
            task = heapq.heappop(self._heap)
            self._not_full.notify()
            return task

    def close(self):
        """Close the queue, waking up all waiting threads."""
        with self._lock:
            self._closed = True
            self._not_empty.notify_all()
            self._not_full.notify_all()

    def is_closed(self) -> bool:
